mapper.select:
SELECT p.product_id, p.name, p.price, p.image_url, p.status, p.stock_quantity, p.main_category, p.created_at, p.manufacturer, (SELECT COUNT(*) FROM tbl_product_options po WHERE po.product_id = p.product_id) as option_count FROM tbl_products p WHERE 1=1
AND p.status = #{status}
AND p.main_category = #{mainCategory}
AND p.sub_category = #{subCategory}
AND ( p.name LIKE CONCAT('%', #{searchKeyword}, '%') OR p.description LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY p.${sortBy} ${sortDirection}
ORDER BY p.created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM tbl_products p
WHERE 1=1

    AND p.status = #{status}


    AND p.main_category = #{mainCategory}


    AND p.sub_category = #{subCategory}


    AND (
    p.name LIKE CONCAT('%', #{searchKeyword}, '%')
    OR p.description LIKE CONCAT('%', #{searchKeyword}, '%')
    )
